package com.quickcart.dto; import com.quickcart.entity.Product; public record ProductResponse(Long id,String name,String description,String brand,String categoryName,double mrp,double sellingPrice,double discountPercentage,String unit,String weight,String size,boolean available,int stockQuantity,String deliveryType,String imageAsset){public static ProductResponse of(Product p){return new ProductResponse(p.getId(),p.getName(),p.getDescription(),p.getBrand(),p.getCategory().getName(),p.getMrp(),p.getSellingPrice(),p.getDiscountPercentage(),p.getUnit(),p.getWeight(),p.getSize(),p.isAvailable(),p.getStockQuantity(),p.getDeliveryType(),p.getImageAsset());}}